function artifact=aggregateV4BValidationControlledV2()
root=v4SetupPaths();folder=fullfile(root,'results','validation','track_b','controlled_awgn','B-param-v02','passes');errors=zeros(3,4,3);counts=zeros(4,3);vp=zeros(3,1);falseVp=zeros(3,1);for i=1:20,x=load(fullfile(folder,sprintf('pass_%02d.mat',i)),'result');r=x.result;errors=errors+r.rawErrors;counts=counts+r.denominators;vp=vp+r.vpAccepted;falseVp=falseVp+r.vpFalseAccepted;end;metrics=zeros(size(errors));for region=1:3,for method=1:3,metrics(method,:,region)=reshape(errors(method,:,region),1,4)./counts(:,region).';end,end;fa=falseVp./vp;coverage=vp./counts(1,:).';quality=all(fa(1:2)<=0.02&coverage(1:2)>=0.01&vp(1:2)>=200);performance=struct('stageMinusPaperSer',metrics(2,1,3)-metrics(3,1,3),'stageMinusPaperHardBer',metrics(2,2,3)-metrics(3,2,3),'stageMinusPaperMlBer',metrics(2,3,3)-metrics(3,3,3));artifact=struct('status',ternary(quality,'PASS','FAIL'),'passes',20,'algorithmVersion','Stage55-B-project-path-calibrated-v8','rawErrors',errors,'denominators',counts,'metrics',metrics,'vpAccepted',vp,'vpFalseAccepted',falseVp,'vpFalseAcceptance',fa,'vpCoverage',coverage,'qualityGatePassed',quality,'performance',performance,'conditionsFrozen',true);out=fileparts(folder);save(fullfile(out,'validation.mat'),'artifact','-v7.3');write(fullfile(out,'validation.json'),jsonencode(artifact,'PrettyPrint',true));if ~quality,error('V4:BValidationV2','B validation v2 quality gate failed.');end
end
function x=ternary(ok,a,b),if ok,x='PASS';else,x='FAIL';end,end
function write(path,text),f=fopen(path,'w','n','UTF-8');cl=onCleanup(@()fclose(f));fprintf(f,'%s\n',text);clear cl,end
